const b = $('Webhook').first().json.body;
return [{
  json: {
    leadId: b.leadId,
    name: String(b.name ?? '').trim(),
    email: String(b.email ?? '').trim().toLowerCase(),
    phone: String(b.phone ?? '').replace(/\D/g, ''),
    budget: Number(b.budget) || 0,
    needs: String(b.needs ?? '').trim(),
    propertyId: Number(b.propertyId) || 0,
    viewingTime: b.viewingTime,
  },
}];

const k = $('Chuẩn hoá').first().json;
const p = $input.first().json; // ket qua GET /api/properties/:id (price, area la chuoi)
const price = Number(p.price);
return [{
  json: {
    ...k,
    property: { name: p.name, address: p.address, price, area: Number(p.area), type: p.type },
    budgetRatio: price > 0 ? Math.round((k.budget / price) * 100) : null, // % ngan sach so voi gia
  },
}];

// Gom dữ liệu báo nhân viên (gửi sang sub-workflow "thong-bao-nhan-vien")
const k = $('Chuẩn hoá').first().json;
const ai = $('Basic LLM Chain').first().json.output;
const p = $('Ghép dữ liệu').first().json.property;
const source = String($('Webhook').first().json.body?.source ?? '').toLowerCase();
const webUrl = String($env.PUBLIC_WEB_URL || 'http://localhost:3000').replace(/\/$/, '');

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const money = (n) => {
  n = Number(n) || 0;
  if (n >= 1e9) return (Math.round(n / 1e7) / 100).toLocaleString('vi-VN') + ' tỷ';
  if (n >= 1e6) return Math.round(n / 1e6).toLocaleString('vi-VN') + ' triệu';
  return n.toLocaleString('vi-VN') + ' đ';
};
const SOURCES = { facebook: 'Facebook', zalo: 'Zalo', google: 'Google', tiktok: 'TikTok', referral: 'Giới thiệu', direct: 'Trực tiếp' };
const sourceText = SOURCES[source] ?? (source || 'Trực tiếp');
const t = DateTime.fromISO(k.viewingTime).setZone('Asia/Ho_Chi_Minh');
const thu = ['', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy', 'Chủ nhật'][t.weekday];
const timeText = t.toFormat('HH:mm') + ' · ' + thu + ' ' + t.toFormat('dd/MM/yyyy');

const resume = $execution.resumeUrl + ($execution.resumeUrl.includes('?') ? '&' : '?');
const approveUrl = resume + 'action=approve';
const rescheduleUrl = resume + 'action=reschedule';
const detailUrl = webUrl + '/admin/leads/' + k.leadId;

const color = { HOT: '#dc2626', WARM: '#f59e0b', COLD: '#6b7280' }[ai.level] ?? '#2563eb';
const row = (label, value) => '<tr><td style="padding:10px;color:#6b7280;width:35%">' + label + '</td><td style="padding:10px">' + value + '</td></tr>';
const btn = (url, label, bg) => '<a href="' + esc(url) + '" style="background:' + bg + ';color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block;margin:0 6px 6px 0">' + label + '</a>';
const emailHtml = '<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden">'
  + '<div style="background:' + color + ';color:#ffffff;padding:20px;font-size:20px;font-weight:bold">Khách ' + esc(ai.level) + ' - cần duyệt lịch xem nhà</div>'
  + '<div style="padding:24px;color:#111827;line-height:1.7;font-size:15px">'
  + '<p style="margin-top:0"><b>Điểm AI: ' + esc(ai.score) + '/100</b> &mdash; ' + esc(ai.reason) + '</p>'
  + '<table style="width:100%;border-collapse:collapse;background:#f3f4f6">'
  + row('Khách hàng', '<b>' + esc(k.name) + '</b>')
  + row('Số điện thoại', esc(k.phone))
  + row('Email', esc(k.email))
  + row('Ngân sách', esc(Number(k.budget).toLocaleString('vi-VN')) + ' VND')
  + row('Nguồn khách', esc(sourceText))
  + row('Nhu cầu', esc(k.needs || '(không ghi)'))
  + row('Căn nhà', esc(p.name) + ', ' + esc(p.address))
  + row('Giờ xem nhà', '<b>' + esc(timeText) + '</b>')
  + '</table>'
  + '<p style="margin-top:20px;padding:12px;background:#fffbeb;border-left:4px solid #f59e0b"><b>Gợi ý của AI:</b> ' + esc(ai.staffNote) + '</p>'
  + '<p style="margin-top:20px">' + btn(approveUrl, 'Duyệt lịch', '#16a34a') + btn(rescheduleUrl, 'Đổi giờ', '#6b7280') + btn(detailUrl, 'Xem chi tiết', '#2563eb') + '</p>'
  + '</div>'
  + '<div style="background:#f9fafb;padding:12px 24px;color:#9ca3af;font-size:12px">Bấm nút trong vòng 24 giờ. Quá hạn, hệ thống sẽ báo cho quản lý.</div>'
  + '</div>';

return [{
  json: {
    leadId: k.leadId,
    level: ai.level,
    title: k.name + ' - ' + ai.score + ' điểm - cần duyệt lịch xem',
    fields: [
      { icon: '👤', label: 'Khách', value: k.name },
      { icon: '📞', label: 'SĐT', value: k.phone },
      { icon: '✉️', label: 'Email', value: k.email },
      { icon: '💰', label: 'Ngân sách', value: money(k.budget) },
      { icon: '📣', label: 'Nguồn', value: sourceText },
      { sep: true },
      { icon: '🏠', label: 'Căn', value: p.name },
      { icon: '📍', label: 'Địa chỉ', value: p.address },
      { icon: '🕙', label: 'Giờ xem', value: timeText },
      { sep: true },
      { icon: '🎯', label: 'Điểm AI', value: ai.score + '/100 (' + ai.level + ')' },
      { icon: '🧠', label: 'Lý do', value: ai.reason },
      { icon: '📝', label: 'Nhu cầu', value: k.needs },
    ],
    note: 'Gợi ý của AI: ' + ai.staffNote,
    actions: [
      { label: '✅ Duyệt lịch', url: approveUrl },
      { label: '🕓 Đổi giờ', url: rescheduleUrl },
      { label: '📋 Xem chi tiết', url: detailUrl },
    ],
    detailUrl,
    emailTo: $('Cấu hình').first().json.staffEmail,
    emailHtml,
  },
}];

