// Sau khi duyệt / đổi giờ / quá hạn: sửa lại tin Telegram đã gửi (thêm dòng trạng thái, bỏ nút Duyệt/Đổi giờ)
const sent = $('Thông báo nhân viên').first().json;
const d = $('Dữ liệu thông báo').first().json;
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat("HH:mm 'ngày' dd/MM");
let statusLine;
if ($('Ghi log APPROVED').isExecuted) statusLine = '✅ ĐÃ DUYỆT lúc ' + now + ' — đã gửi email chốt lịch cho khách';
else if ($('Ghi log RESCHEDULE_REQUESTED').isExecuted) statusLine = '🕓 ĐÃ YÊU CẦU ĐỔI GIỜ lúc ' + now + ' — đặt giờ mới trên web admin rồi duyệt lại';
else statusLine = '⏰ QUÁ 24 GIỜ CHƯA DUYỆT (' + now + ') — đã báo quản lý, duyệt tiếp trên web admin';

return [{
  json: {
    mode: 'update',
    leadId: d.leadId,
    level: d.level,
    title: d.title,
    fields: d.fields,
    note: d.note,
    statusLine,
    actions: [{ label: '📋 Xem chi tiết', url: d.detailUrl }],
    telegramMessageId: sent.telegramMessageId,
    telegramChatId: sent.telegramChatId,
  },
}];
